import 'package:flutter/material.dart';
import 'profile_controller.dart';
class ChangePasswordScreen extends StatefulWidget{const ChangePasswordScreen({super.key});@override State<ChangePasswordScreen>createState()=>_ChangePasswordScreenState();}
class _ChangePasswordScreenState extends State<ChangePasswordScreen>{final p=TextEditingController(),q=TextEditingController();final c=ProfileController();bool a=true,b=true;@override void dispose(){p.dispose();q.dispose();c.dispose();super.dispose();}Future<void>_save()async{final ok=await c.changePassword(p.text,q.text);if(ok&&mounted){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Password changed successfully.')));Navigator.pop(context);}else if(c.errorMessage!=null&&mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(c.errorMessage!)));} @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Change Password')),body:ListView(padding:const EdgeInsets.all(16),children:[TextField(controller:p,obscureText:a,decoration:InputDecoration(labelText:'New password',suffixIcon:IconButton(onPressed:()=>setState(()=>a=!a),icon:Icon(a?Icons.visibility:Icons.visibility_off)))),TextField(controller:q,obscureText:b,decoration:InputDecoration(labelText:'Confirm password',suffixIcon:IconButton(onPressed:()=>setState(()=>b=!b),icon:Icon(b?Icons.visibility:Icons.visibility_off)))),const SizedBox(height:20),FilledButton(onPressed:c.isChangingPassword?null:_save,child:const Text('Change password'))]));}
